ruleToc.chapterList:
@js:(function(){
var cid=book.bookUrl.replace(/\/+$/,'').split('/').pop();
var re=/<div[^>]*class="[^"]*comics-chapters[^"]*"[^>]*>\s*<a[^>]*href="[^"]*"[^>]*>[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>[\s\S]*?<\/a>/g;
var names=[];var m;
while((m=re.exec(result))){var t=m[1].replace(/<[^>]+>/g,'').trim();if(t)names.push(t);}
var out=[];
for(var i=0;i<names.length;i++){out.push({name:names[i],url:'https://appcn.baozimh.com/baozimhapp/comic/chapter/'+cid+'/0_'+i+'.html'});}
return out;})()

ruleContent.content:
@js:(function(){
var out=[];
var re=/<img[^>]*class="[^"]*comic-contain__item[^"]*"[^>]*data-src="([^"]+)"/g;
var m;
while((m=re.exec(result))){
  var u=m[1];
  var mm=u.match(/^(https?:\/\/)?([^/\s:]+)(:\d+)?(\/[a-z]comic\/.*)/);
  if(mm){u=(mm[1]||'https://')+mm[2]+'/w640'+mm[4];}
  out.push('<img src="'+u+'">');
}
return out.join('\n');})()

ruleExplore.bookList:
@js:(function(){
var d=JSON.parse(result).items||[];var out=[];
for(var i=0;i<d.length;i++){var e=d[i];
  out.push({name:e.name||'',author:e.author||'',coverUrl:'https://static-tw.baozimh.com/cover/'+(e.topic_img||'')+'?w=285&h=375&q=100',bookUrl:'https://cn.bzmgcn.com/comic/'+e.comic_id,intro:e.introduction||''});
}return out;})()
